const raw = $input.first().json || {};
const body = (raw.body && raw.event == null) ? raw.body : raw;
const event = String(body.event || '');
const data = body.data || {};
const allowed = event === 'charge.success' || event === 'paymentrequest.success';
if (!allowed) {
  return [];
}
let verify_url = '';
let kind = '';
if (event === 'charge.success') {
  const ref = String(data.reference || '').trim();
  if (!ref) return [];
  kind = 'transaction';
  verify_url = 'https://api.paystack.co/transaction/verify/' + encodeURIComponent(ref);
} else {
  const code = String(data.request_code || data.id || '').trim();
  if (!code) return [];
  kind = 'paymentrequest';
  verify_url = 'https://api.paystack.co/paymentrequest/verify/' + encodeURIComponent(code);
}
return [{ json: { event, kind, verify_url, hint_invoice_id: String((data.metadata && data.metadata.zoho_invoice_id) || '') } }];

function asMeta(raw) {
  if (!raw) return {};
  if (typeof raw === 'string') {
    try { return JSON.parse(raw); } catch (e) { return {}; }
  }
  return raw;
}
const parsed = $('Parse event').item.json;
const res = $input.first().json || {};
const data = res.data || {};
if (res.status === false) return [];
const meta = asMeta(data.metadata);
const invoiceId = String(meta.zoho_invoice_id || parsed.hint_invoice_id || '').trim();
const paid = parsed.kind === 'transaction'
  ? String(data.status || '').toLowerCase() === 'success'
  : data.paid === true || String(data.status || '').toLowerCase() === 'success';
if (!paid || !invoiceId) return [];
const kobo = Number(data.amount);
const naira = Number.isFinite(kobo) ? kobo / 100 : 0;
const reference = String(data.reference || data.request_code || data.offline_reference || '').slice(0, 100);
let channel = String(data.channel || '').toLowerCase();
let payment_mode = 'others';
if (channel === 'card') payment_mode = 'creditcard';
else if (channel === 'bank' || channel === 'bank_transfer' || parsed.kind === 'paymentrequest') payment_mode = 'banktransfer';
const paidAt = String(data.paid_at || data.paidAt || '').slice(0, 10);
const date = /^\d{4}-\d{2}-\d{2}$/.test(paidAt)
  ? paidAt
  : new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Lagos' }).format(new Date());
return [{ json: {
  zoho_invoice_id: invoiceId,
  zoho_customer_id: String(meta.zoho_customer_id || ''),
  naira,
  kobo,
  reference,
  payment_mode,
  date,
  paystack: data
} }];

function deskSetting(key, fallback) {
  try {
    const s = $('Fetch desk settings').first().json || {};
    const v = s[key];
    if (v != null && String(v).trim() !== '') return String(v).trim();
  } catch (e) {}
  return fallback;
}
const p = $('Stamp verified').item.json;
return [{ json: { ...p, organization_id: deskSetting('zoho.organization_id', '939049468'), deposit_to_account_id: deskSetting('zoho.deposit_to_account_id', '') } }];

const p = $('Attach org').item.json;
const res = $input.first().json || {};
const inv = res.invoice || {};
if (!inv.invoice_id) return [];
const balance = Number(inv.balance);
const status = String(inv.status || '').toLowerCase();
if (status === 'paid' || (Number.isFinite(balance) && balance <= 0)) return [];
const apply = Number.isFinite(balance) ? Math.min(p.naira, balance) : p.naira;
if (!(apply > 0)) return [];
const body = {
  customer_id: String(inv.customer_id || p.zoho_customer_id),
  payment_mode: p.payment_mode || 'banktransfer',
  amount: apply,
  date: p.date,
  reference_number: p.reference,
  description: 'Paystack ' + p.reference,
  invoices: [{ invoice_id: String(inv.invoice_id), amount_applied: apply }]
};
if (p.deposit_to_account_id) body.account_id = p.deposit_to_account_id;
return [{ json: { organization_id: p.organization_id, body, invoice: inv } }];

const built = $('Build Books payment').item.json;
const res = $input.first().json || {};
const pay = res.payment || {};
if (res.code && res.code !== 0 && !pay.payment_id) {
  return [{ json: { received: true, booked: false, reason: String(res.message || JSON.stringify(res)).slice(0, 400), invoice_id: built.body && built.body.invoices && built.body.invoices[0] && built.body.invoices[0].invoice_id } }];
}
return [{ json: { received: true, booked: true, payment_id: pay.payment_id, invoice_id: (pay.invoices && pay.invoices[0] && pay.invoices[0].invoice_id) || (built.invoice && built.invoice.invoice_id) } }];
